CREATE TABLE accounts (id UUID PRIMARY KEY, owner_type TEXT NOT NULL CHECK (owner_type IN ('USER','MERCHANT','SYSTEM')), owner_id TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('USER_WALLET','MERCHANT_PAYABLE','PSP_SUSPENSE','FEE_INCOME')), currency VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(owner_type, owner_id, type, currency));
CREATE TABLE account_balances (account_id UUID PRIMARY KEY REFERENCES accounts(id), balance BIGINT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ledger_transactions (id UUID PRIMARY KEY, type TEXT NOT NULL CHECK (type IN ('PAYMENT','REFUND','REVERSAL','FEE')), reference_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ledger_entries (id BIGSERIAL PRIMARY KEY, transaction_id UUID NOT NULL REFERENCES ledger_transactions(id), account_id UUID NOT NULL REFERENCES accounts(id), direction TEXT NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), amount BIGINT NOT NULL CHECK (amount > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_ledger_entries_account_created ON ledger_entries(account_id, created_at DESC);
CREATE INDEX idx_ledger_entries_transaction ON ledger_entries(transaction_id);
CREATE TABLE payments (id UUID PRIMARY KEY, merchant_id TEXT NOT NULL, payer_account UUID NOT NULL REFERENCES accounts(id), payee_account UUID NOT NULL REFERENCES accounts(id), amount BIGINT NOT NULL CHECK (amount > 0), currency VARCHAR(3) NOT NULL, status TEXT NOT NULL CHECK (status IN ('INITIATED','HELD','AUTHORIZED','PENDING','SETTLED','FAILED','REVERSED')), psp_reference TEXT, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_payments_merchant_created ON payments(merchant_id, created_at DESC);
CREATE TABLE payment_status_history (id BIGSERIAL PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), status TEXT NOT NULL, psp_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_payment_history_payment ON payment_status_history(payment_id, created_at);
CREATE TABLE idempotency_keys (id BIGSERIAL PRIMARY KEY, merchant_id TEXT NOT NULL, idem_key TEXT NOT NULL, request_hash CHAR(64) NOT NULL, status TEXT NOT NULL CHECK (status IN ('IN_PROGRESS','COMPLETED')), resource_id UUID, response_code INT, response_body JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(merchant_id, idem_key));
CREATE TABLE outbox (id UUID PRIMARY KEY, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, event_type TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, attempts INT NOT NULL DEFAULT 0, last_error TEXT);
CREATE INDEX idx_outbox_pending ON outbox(published_at, created_at);
CREATE TABLE psp_webhook_events (psp_event_id TEXT PRIMARY KEY, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refunds (id UUID PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), amount BIGINT NOT NULL CHECK (amount > 0), status TEXT NOT NULL CHECK (status IN ('PENDING','COMPLETED','FAILED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_refunds_payment ON refunds(payment_id, created_at);
CREATE OR REPLACE FUNCTION enforce_ledger_balance() RETURNS TRIGGER LANGUAGE plpgsql AS $$ DECLARE imbalance BIGINT; BEGIN SELECT COALESCE(SUM(CASE WHEN direction='DEBIT' THEN amount ELSE -amount END),0) INTO imbalance FROM ledger_entries WHERE transaction_id=NEW.transaction_id; IF imbalance <> 0 THEN RAISE EXCEPTION 'ledger transaction % unbalanced', NEW.transaction_id USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER ledger_balance_trigger AFTER INSERT OR UPDATE ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_ledger_balance();
